create table alerts (actual_value numeric(10,2) not null, threshold_value numeric(10,2) not null, created_at timestamp(6) not null, occurred_at timestamp(6) with time zone not null, resolved_at timestamp(6) with time zone, updated_at timestamp(6) not null, device_id uuid not null, id uuid not null, space_id uuid, message varchar(500) not null, device_name varchar(255), metric varchar(255) not null check (metric in ('PM25','CO2','TEMPERATURE','HUMIDITY')), severity varchar(255) not null check (severity in ('CRITICAL','WARNING','LOW')), space_name varchar(255), status varchar(255) not null check (status in ('ACTIVE','ACKNOWLEDGED','RESOLVED')), primary key (id));
create table device_analytics_snapshots (aqi_value integer not null, average_co2 float(53) not null, average_humidity float(53) not null, average_pm2_5 float(53) not null, average_temperature float(53) not null, created_at timestamp(6) not null, time_window_end timestamp(6) with time zone not null, time_window_start timestamp(6) with time zone not null, updated_at timestamp(6) not null, device_id uuid not null, id uuid not null, aqi_category varchar(255) not null check (aqi_category in ('GOOD','MODERATE','UNHEALTHY_FOR_SENSITIVE','UNHEALTHY','VERY_UNHEALTHY','HAZARDOUS')), primary key (id));
create table device_assignment_configuration (assignment_id uuid not null, config_key varchar(255) not null, config_value varchar(255), primary key (assignment_id, config_key));
create table device_assignments (activated_at timestamp(6) with time zone, created_at timestamp(6) not null, last_seen_at timestamp(6) with time zone, updated_at timestamp(6) not null, device_id uuid not null unique, id uuid not null, owner_user_id uuid, space_id uuid, claim_token varchar(255) unique, status varchar(255) not null check (status in ('OFFLINE','ONLINE','STANDBY','ERROR','MAINTENANCE','DECOMMISSIONED')), primary key (id));
create table device_commands (created_at timestamp(6) not null, executed_at timestamp(6) with time zone, sent_at timestamp(6) with time zone, updated_at timestamp(6) not null, device_id uuid not null, id uuid not null, failure_reason text, payload text, status varchar(255) not null check (status in ('PENDING','SENT','EXECUTED','FAILED','EXPIRED')), type varchar(255) not null check (type in ('STANDBY','WAKE','RESTART')), primary key (id));
create table device_daily_summaries (aqi_delta_pct float(53), average_aqi integer not null, co2_avg float(53) not null, co2_max float(53) not null, co2_min float(53) not null, humidity_avg float(53) not null, humidity_max float(53) not null, humidity_min float(53) not null, peak_pm2_5 float(53) not null, pm2_5_avg float(53) not null, pm2_5_max float(53) not null, pm2_5_min float(53) not null, summary_date date not null, temperature_avg float(53) not null, temperature_max float(53) not null, temperature_min float(53) not null, cat_good bigint not null, cat_hazardous bigint not null, cat_moderate bigint not null, cat_unhealthy bigint not null, cat_unhealthy_sensitive bigint not null, cat_very_unhealthy bigint not null, created_at timestamp(6) not null, peak_pm2_5_at timestamp(6) with time zone not null, reading_count bigint not null, updated_at timestamp(6) not null, device_id uuid not null, id uuid not null, dominant_aqi_category varchar(255) not null check (dominant_aqi_category in ('GOOD','MODERATE','UNHEALTHY_FOR_SENSITIVE','UNHEALTHY','VERY_UNHEALTHY','HAZARDOUS')), primary key (id), unique (device_id, summary_date));
create table device_monthly_summaries (aqi_delta_pct float(53), average_aqi integer not null, co2_avg float(53) not null, co2_max float(53) not null, co2_min float(53) not null, days_covered integer not null, humidity_avg float(53) not null, humidity_max float(53) not null, humidity_min float(53) not null, peak_pm2_5 float(53) not null, pm2_5_avg float(53) not null, pm2_5_max float(53) not null, pm2_5_min float(53) not null, summary_month date not null, temperature_avg float(53) not null, temperature_max float(53) not null, temperature_min float(53) not null, cat_good bigint not null, cat_hazardous bigint not null, cat_moderate bigint not null, cat_unhealthy bigint not null, cat_unhealthy_sensitive bigint not null, cat_very_unhealthy bigint not null, created_at timestamp(6) not null, peak_pm2_5_at timestamp(6) with time zone not null, reading_count bigint not null, updated_at timestamp(6) not null, device_id uuid not null, id uuid not null, dominant_aqi_category varchar(255) not null check (dominant_aqi_category in ('GOOD','MODERATE','UNHEALTHY_FOR_SENSITIVE','UNHEALTHY','VERY_UNHEALTHY','HAZARDOUS')), primary key (id), unique (device_id, summary_month));
create table devices (deleted boolean not null, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, api_key varchar(255) not null unique, device_type varchar(255) not null, factory_name varchar(255) not null, hardware_id varchar(255) not null unique, name varchar(255) not null, serial_number varchar(255) not null unique, primary key (id));
create table email_logs (sent boolean not null, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, content TEXT, error_message varchar(255), recipient_email varchar(255) not null, subject varchar(255) not null, primary key (id));
create table organizations (created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, user_id uuid, name varchar(255) not null, primary key (id));
create table payment_record (amount bigint, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, user_id uuid, currency varchar(255), status varchar(255) check (status in ('PENDING','COMPLETED','FAILED')), stripe_payment_intent_id varchar(255), primary key (id));
create table push_notification_logs (sent boolean not null, created_at timestamp(6) not null, updated_at timestamp(6) not null, alert_id uuid, id uuid not null, user_id uuid not null, error_message varchar(255), message TEXT not null, title varchar(255) not null, primary key (id));
create table spaces (created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, organization_id uuid not null, user_id uuid, name varchar(255) not null, primary key (id));
create table telemetry_evaluations (aq_co2 float(53) not null, aq_humidity float(53) not null, aq_temperature float(53) not null, conn_signal_strength integer, device_time time(6) not null, health_status integer not null, pm_pm10 integer not null, pm_pm1_0 integer not null, pm_pm2_5 integer not null, created_at timestamp(6) not null, recorded_at timestamp(6) with time zone not null, updated_at timestamp(6) not null, uptime_seconds bigint not null, device_id uuid not null, id uuid not null, conn_network varchar(255), conn_status varchar(255) not null, location_country varchar(255), status varchar(255) not null, primary key (id));
create table user_plan (end_date date, start_date date, created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, user_id uuid, plan_type varchar(255) check (plan_type in ('FREEMIUM','PREMIUM')), primary key (id));
create table users (created_at timestamp(6) not null, updated_at timestamp(6) not null, id uuid not null, address varchar(255) not null unique, oauth_provider varchar(255) check (oauth_provider in ('MAIL','GOOGLE')), oauth_subject varchar(255), password_hash varchar(255), status varchar(255) not null check (status in ('PENDING_VERIFICATION','ACTIVE','SUSPENDED')), primary key (id));
create index idx_alert_device_metric_status on alerts (device_id, metric, status);
create index idx_alert_space_status on alerts (space_id, status);
create index idx_alert_occurred_at on alerts (occurred_at);
create index idx_devices_updated_at on devices (updated_at);
create index idx_telemetry_eval_device_recorded on telemetry_evaluations (device_id, recorded_at);
alter table if exists device_assignment_configuration add constraint FKj61t9phd51qo9s6w67jiy35lg foreign key (assignment_id) references device_assignments;
alter table if exists device_assignments add constraint FKt90oda68w2myhlkgby5kgle89 foreign key (device_id) references devices;
alter table if exists device_commands add constraint FK3dklwed1f2hb3bqrxwp0a8jyd foreign key (device_id) references devices;
